O cartão abaixo aparece com um fade ao abrir a tela. O que acontece quando o usuário toca em **Curtir**, e por quê?

```jsx
export default function CartaoProduto({ produto }) {
  const [curtido, setCurtido] = useState(false);
  const entrada = new Animated.Value(0);

  useEffect(() => {
    Animated.timing(entrada, { toValue: 1, duration: 300, useNativeDriver: true }).start();
  }, []);

  return (
    <Animated.View style={{ opacity: entrada }}>
      <Text>{produto.nome}</Text>
      <Pressable onPress={() => setCurtido(!curtido)}><Text>Curtir</Text></Pressable>
    </Animated.View>
  );
}
```

