const CHANCE_DE_ERRO = 0.3;

function carregar() {
  setCarregando(true);
  setErro(null);
  setTimeout(() => {
    if (Math.random() < CHANCE_DE_ERRO) setErro('Não conseguimos buscar os produtos.');
    setCarregando(false);
  }, 1500);
}
